param([string]$InputDoc='orchestration/engine-work/final-closure/long/chartex-only.docx',[string]$OutputDoc='orchestration/engine-work/final-closure/long/chartex-chart-edited.docx',[string]$Report='orchestration/engine-work/final-closure/long/chartex-chart-edit.json')
$ErrorActionPreference='Stop';$word=$null;$doc=$null;$owns=$false;$result=@{status='FAIL'}
try{
 $before=@(Get-Process WINWORD -ErrorAction SilentlyContinue|ForEach-Object{$_.Id});$word=New-Object -ComObject Word.Application;$created=@(Get-Process WINWORD -ErrorAction SilentlyContinue|Where-Object{$_.Id -notin $before});if($created.Count -ne 1){throw 'Cannot establish one owned Word instance'};$owns=$true;$result.pid=$created[0].Id;Write-Output ('WORDPID:'+$result.pid);$word.Visible=$false;$word.DisplayAlerts=0
 $result.stage='open';$doc=$word.Documents.Open((Resolve-Path $InputDoc).Path,[ref]$false,[ref]$false);$charts=@();foreach($s in $doc.Shapes){if($s.HasChart -eq -1){$charts+=,$s.Chart}};foreach($s in $doc.InlineShapes){if($s.HasChart -eq -1){$charts+=,$s.Chart}};if($charts.Count -lt 1){throw 'Chart missing'};$chart=$charts[0];$result.chartType=$chart.ChartType;$result.seriesCount=$chart.SeriesCollection().Count;$result.chartTitleBefore=$chart.ChartTitle.Text
 $result.stage='edit-chart';$chart.ChartTitle.Format.TextFrame2.TextRange.Text='ChartEx edit proof';$result.chartTitleEdited=$chart.ChartTitle.Text
 $result.stage='save';$out=[IO.Path]::GetFullPath($OutputDoc);$doc.SaveAs2([ref]$out,[ref]16);$doc.Close([ref]$false);[void][Runtime.InteropServices.Marshal]::FinalReleaseComObject($doc);$doc=$null
 $result.stage='reopen';$doc=$word.Documents.Open($out,[ref]$false,[ref]$true);$charts=@();foreach($s in $doc.Shapes){if($s.HasChart -eq -1){$charts+=,$s.Chart}};foreach($s in $doc.InlineShapes){if($s.HasChart -eq -1){$charts+=,$s.Chart}};$result.chartCountReopened=$charts.Count;$result.chartTypeReopened=$charts[0].ChartType;$result.chartTitleReopened=$charts[0].ChartTitle.Text;$result.seriesCountReopened=$charts[0].SeriesCollection().Count;if($result.chartTitleReopened -ne 'ChartEx edit proof'){throw 'Chart edit did not persist'};$result.status='PASS'
}catch{$result.error=$_.Exception.Message}finally{if($doc){try{$doc.Close([ref]$false)}catch{};[void][Runtime.InteropServices.Marshal]::FinalReleaseComObject($doc)};if($word){if($owns){try{$word.Quit()}catch{}};[void][Runtime.InteropServices.Marshal]::FinalReleaseComObject($word)};$result|ConvertTo-Json -Depth 6|Set-Content $Report -Encoding UTF8};Write-Output($result|ConvertTo-Json -Compress);if($result.status -ne 'PASS'){exit 1}

